#!/usr/bin/env bash
set -euo pipefail
ROOT="${ROOT:-/teams/ius_1663576043/hby/rl/ov2}"; PYTHON="${PYTHON:-/root/miniconda3/envs/myconda/bin/python}"; MODE="${MODE:-smoke}"; TS="${TS:-$(date +%Y%m%d-%H%M%S)}"
cd "${ROOT}"; source "${ROOT}/experiments/repro_env.sh" 2>/dev/null || true
export PYTHONUNBUFFERED=1 XLA_PYTHON_CLIENT_PREALLOCATE="${XLA_PYTHON_CLIENT_PREALLOCATE:-false}" PYTHONPATH="${ROOT}/experiments:${ROOT}/JaxMARL:${PYTHONPATH:-}"
SEED="${SEED:-42}"; WANDB_ENTITY="${WANDB_ENTITY:-huiby_tsinghua23}"; WANDB_PROJECT="${WANDB_PROJECT:-ov2-paper-repro}"; SOURCE_BACKEND="${SOURCE_BACKEND:-mappo}"
SOURCE_RUN_FILE="${SOURCE_RUN_FILE:-runs_by_config/counter_circuit_full_obs_64env_16mb_10M/mappo/rnn_state_aug/mappo_rnn_state_aug_64_16/RUN_PATH.txt}"; SOURCE_RUN="${SOURCE_RUN:-}"; [ -n "${SOURCE_RUN}" ] || SOURCE_RUN="$(cat "${SOURCE_RUN_FILE}" 2>/dev/null || true)"
if [ -z "${SOURCE_RUN}" ] || [ ! -d "${SOURCE_RUN}" ]; then
  SOURCE_RUN="${SOURCE_RUN_FALLBACK:-runs/mappo_critic_ablation_64_16_mappo_rnn_state_aug_critic_local_obs_20260512-114032/20260512-124057_ld4pavec_counter_circuit_avs-full}"
fi
if [ ! -d "${SOURCE_RUN}" ]; then echo "Missing SOURCE_RUN directory: ${SOURCE_RUN}" >&2; exit 1; fi
if [ "${MODE}" = smoke ]; then NUM_SEEDS="${NUM_SEEDS:-1}"; TOTAL_TIMESTEPS="${TOTAL_TIMESTEPS:-262144}"; REW_SHAPING_HORIZON="${REW_SHAPING_HORIZON:-131072}"; EVAL_SEEDS="${EVAL_SEEDS:-4}"; EVAL_BATCHES="${EVAL_BATCHES:-1}"; WANDB_MODE="${WANDB_MODE:-disabled}"; GAMMA_DATA_EPISODES="${GAMMA_DATA_EPISODES:-16}"; GAMMA_VAE_EPOCHS="${GAMMA_VAE_EPOCHS:-2}"; GAMMA_VAE_STEPS_PER_EPOCH="${GAMMA_VAE_STEPS_PER_EPOCH:-2}"; else NUM_SEEDS="${NUM_SEEDS:-10}"; TOTAL_TIMESTEPS="${TOTAL_TIMESTEPS:-10000000}"; REW_SHAPING_HORIZON="${REW_SHAPING_HORIZON:-5000000}"; EVAL_SEEDS="${EVAL_SEEDS:-500}"; EVAL_BATCHES="${EVAL_BATCHES:-10}"; WANDB_MODE="${WANDB_MODE:-online}"; GAMMA_DATA_EPISODES="${GAMMA_DATA_EPISODES:-1024}"; GAMMA_VAE_EPOCHS="${GAMMA_VAE_EPOCHS:-80}"; GAMMA_VAE_STEPS_PER_EPOCH="${GAMMA_VAE_STEPS_PER_EPOCH:-100}"; fi
NUM_ENVS="${NUM_ENVS:-64}"; NUM_STEPS="${NUM_STEPS:-256}"; UPDATE_EPOCHS="${UPDATE_EPOCHS:-4}"; NUM_MINIBATCHES="${NUM_MINIBATCHES:-16}"
TTAC_ADAPTER_SCALE="${TTAC_ADAPTER_SCALE:-0.5}"; TTAC_AGREEMENT_COEF="${TTAC_AGREEMENT_COEF:-0.05}"; TTAC_TRAIN_KL_COEF="${TTAC_TRAIN_KL_COEF:-0.005}"; TTAC_TEST_HIST_KL_COEF="${TTAC_TEST_HIST_KL_COEF:-0.0}"; TTAC_TEST_EGO_KL_COEF="${TTAC_TEST_EGO_KL_COEF:-0.01}"; TTAC_TEST_CUR_KL_COEF="${TTAC_TEST_CUR_KL_COEF:-0.01}"; TTAC_TEST_UPDATE_STEPS="${TTAC_TEST_UPDATE_STEPS:-3}"; TTAC_TEST_LR="${TTAC_TEST_LR:-0.003}"; TTAC_HISTORY_LEN="${TTAC_HISTORY_LEN:-50}"; TTAC_ONLINE_EVAL_PAIRINGS_PER_CHUNK="${TTAC_ONLINE_EVAL_PAIRINGS_PER_CHUNK:-9}"
RUN_ROOT="${RUN_ROOT:-runs/gamma_ttac_mappo_state_aug_full_${TS}}"; DATASET="${RUN_ROOT}/dataset/gamma_ttac_population.npz"; VAE_DIR="${RUN_ROOT}/vae"; mkdir -p "${RUN_ROOT}/dataset" "${VAE_DIR}"
echo "[$(date +%F' '%T)] GAMMA-TTAC source=${SOURCE_RUN}"
"${PYTHON}" -m overcooked_v2_experiments.gamma_ttac.collect_dataset --backend "${SOURCE_BACKEND}" --run-dir "${SOURCE_RUN}" --output "${DATASET}" --seed "${SEED}" --num-episodes "${GAMMA_DATA_EPISODES}" --max-pairs "${GAMMA_DATA_MAX_PAIRS:-100}" --cross --validation-ratio 0.1
"${PYTHON}" -m overcooked_v2_experiments.gamma_ttac.train_vae --dataset "${DATASET}" --output-dir "${VAE_DIR}" --seed "${SEED}" --z-dim "${GAMMA_Z_DIM:-32}" --hidden-dim "${GAMMA_HIDDEN_DIM:-128}" --chunk-length "${GAMMA_CHUNK_LENGTH:-100}" --batch-size "${GAMMA_VAE_BATCH_SIZE:-64}" --epochs "${GAMMA_VAE_EPOCHS}" --steps-per-epoch "${GAMMA_VAE_STEPS_PER_EPOCH}" --lr "${GAMMA_VAE_LR:-0.001}" --kl-coef "${GAMMA_VAE_KL_COEF:-0.1}"
PREFIX="gamma_ttac_mappo_state_aug_data_${NUM_ENVS}_${NUM_MINIBATCHES}_${TOTAL_TIMESTEPS}_${TS}"
"${PYTHON}" -m overcooked_v2_experiments.gamma_ttac.main env=counter_circuit SEED="${SEED}" NUM_SEEDS="${NUM_SEEDS}" NUM_CHECKPOINTS=3 VISUALIZE=False OPTIONAL_PREFIX="${PREFIX}" wandb.ENTITY="${WANDB_ENTITY}" wandb.PROJECT="${WANDB_PROJECT}" wandb.WANDB_MODE="${WANDB_MODE}" GAMMA.VAE_CHECKPOINT="${VAE_DIR}/gamma_vae.pkl" model.TOTAL_TIMESTEPS="${TOTAL_TIMESTEPS}" model.REW_SHAPING_HORIZON="${REW_SHAPING_HORIZON}" model.NUM_ENVS="${NUM_ENVS}" model.NUM_STEPS="${NUM_STEPS}" model.UPDATE_EPOCHS="${UPDATE_EPOCHS}" model.NUM_MINIBATCHES="${NUM_MINIBATCHES}" model.TTAC_ADAPTER_SCALE="${TTAC_ADAPTER_SCALE}" model.TTAC_AGREEMENT_COEF="${TTAC_AGREEMENT_COEF}" model.TTAC_TRAIN_KL_COEF="${TTAC_TRAIN_KL_COEF}" model.TTAC_TEST_HIST_KL_COEF="${TTAC_TEST_HIST_KL_COEF}" model.TTAC_TEST_EGO_KL_COEF="${TTAC_TEST_EGO_KL_COEF}" model.TTAC_TEST_CUR_KL_COEF="${TTAC_TEST_CUR_KL_COEF}" model.TTAC_TEST_UPDATE_STEPS="${TTAC_TEST_UPDATE_STEPS}" model.TTAC_TEST_LR="${TTAC_TEST_LR}" model.TTAC_HISTORY_LEN="${TTAC_HISTORY_LEN}"
RUN_DIR="$(find runs -maxdepth 2 -type d -path "*${PREFIX}*" | sort | tail -n 1)"; echo "${RUN_DIR}" > "${RUN_ROOT}/gamma_ttac_run_dir.txt"
for mode in base_no_test_adapt ttac_true_history ttac_wrong_history ttac_adapter_off; do
  echo "[$(date +%F' '%T)] Eval ${mode} SP"
  "${PYTHON}" -m overcooked_v2_experiments.ttac_v2.utils.visualize_ppo --d "${RUN_DIR}" --num_seeds "${EVAL_SEEDS}" --no_viz --seed "${SEED}" --ttac_mode "${mode}" --output_tag "${mode}" --eval_batches "${EVAL_BATCHES}"     --ttac_adapter_scale "${TTAC_ADAPTER_SCALE}" --ttac_test_hist_kl_coef "${TTAC_TEST_HIST_KL_COEF}" --ttac_test_ego_kl_coef "${TTAC_TEST_EGO_KL_COEF}" --ttac_test_cur_kl_coef "${TTAC_TEST_CUR_KL_COEF}" --ttac_test_lr "${TTAC_TEST_LR}" --ttac_test_update_steps "${TTAC_TEST_UPDATE_STEPS}" --ttac_history_len "${TTAC_HISTORY_LEN}" --online_eval_pairings_per_chunk "${TTAC_ONLINE_EVAL_PAIRINGS_PER_CHUNK:-9}"
  echo "[$(date +%F' '%T)] Eval ${mode} cross"
  "${PYTHON}" -m overcooked_v2_experiments.ttac_v2.utils.visualize_ppo --d "${RUN_DIR}" --cross --num_seeds "${EVAL_SEEDS}" --no_viz --seed "${SEED}" --ttac_mode "${mode}" --output_tag "${mode}" --eval_batches "${EVAL_BATCHES}"     --ttac_adapter_scale "${TTAC_ADAPTER_SCALE}" --ttac_test_hist_kl_coef "${TTAC_TEST_HIST_KL_COEF}" --ttac_test_ego_kl_coef "${TTAC_TEST_EGO_KL_COEF}" --ttac_test_cur_kl_coef "${TTAC_TEST_CUR_KL_COEF}" --ttac_test_lr "${TTAC_TEST_LR}" --ttac_test_update_steps "${TTAC_TEST_UPDATE_STEPS}" --ttac_history_len "${TTAC_HISTORY_LEN}" --online_eval_pairings_per_chunk "${TTAC_ONLINE_EVAL_PAIRINGS_PER_CHUNK:-9}"
done

